    run_col = run_line.find('run:')
    if run_col < 0:
        run_col = len(run_line) - len(run_line.lstrip())
    colon = run_line.find(':', run_col)
    value_start = colon + 1
    while value_start < len(run_line) and run_line[value_start] in ' \t':
        value_start += 1
    if run_row == expr_row and value_start < len(run_line) and run_line[value_start] not in '|>':
        script_row, script_col = run_row, value_start
        script = run_line[script_col:]
